CREATE TABLE support_tickets(id BINARY(16) PRIMARY KEY,ticket_number VARCHAR(30) NOT NULL UNIQUE,tenant_id BINARY(16) NOT NULL,requester_id BINARY(16),requester_name VARCHAR(120) NOT NULL,requester_email VARCHAR(190) NOT NULL,subject VARCHAR(200) NOT NULL,description TEXT NOT NULL,category VARCHAR(50) NOT NULL,priority VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,assignee_id BINARY(16),assignee_name VARCHAR(120),station_id BINARY(16),session_id BINARY(16),sla_due_at TIMESTAMP(6),first_response_at TIMESTAMP(6),resolved_at TIMESTAMP(6),closed_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL DEFAULT 0,INDEX idx_support_tenant_status(tenant_id,status),INDEX idx_support_assignee(assignee_id));
CREATE TABLE support_ticket_comments(id BINARY(16) PRIMARY KEY,ticket_id BINARY(16) NOT NULL,author_id BINARY(16),author_name VARCHAR(120) NOT NULL,body TEXT NOT NULL,internal_note BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_support_comment_ticket FOREIGN KEY(ticket_id)REFERENCES support_tickets(id),INDEX idx_support_comments(ticket_id,created_at));
CREATE TABLE support_ticket_events(id BINARY(16) PRIMARY KEY,ticket_id BINARY(16) NOT NULL,event_type VARCHAR(40) NOT NULL,from_value VARCHAR(120),to_value VARCHAR(120),actor_id BINARY(16),actor_name VARCHAR(120),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_support_event_ticket FOREIGN KEY(ticket_id)REFERENCES support_tickets(id),INDEX idx_support_events(ticket_id,created_at));
